---@class UIFishPoolDriftingBottleDialog
local UIFishPoolDriftingBottleDialog = Class("UIFishPoolDriftingBottleDialog")

function UIFishPoolDriftingBottleDialog:__init() 
end

function UIFishPoolDriftingBottleDialog:__delete()
end

function UIFishPoolDriftingBottleDialog:Awake()
    SetButtonAction(self.Root, Bind(self, self.OnBtnOpen))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnClose))

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end

    self._data = checkTable(argument.data)
    self._cb = argument.cb

end

function UIFishPoolDriftingBottleDialog:FillSelf(vo)
    if not vo then
        return
    end

    if checkNumber(vo.type) == 5 then
        self:FillPhoto(vo)
    elseif checkNumber(vo.type) == 4 then    --明信片
        self:FillContent(vo)
    end
end

--明信片
function UIFishPoolDriftingBottleDialog:FillContent(vo)
    CfUtils.SetActive(self.PhotoNode, false)
    CfUtils.SetActive(self.TextNode, true)

    CfUtils.FillText(self.TextTitle2, vo.title)
    CfUtils.FillText(self.TextContent2, vo.content)
end 

function UIFishPoolDriftingBottleDialog:FillPhoto(vo)
    CfUtils.SetActive(self.PhotoNode, true)
    CfUtils.SetActive(self.TextNode, false)

    CfUtils.FillText(self.TextTitle, vo.title)
    CfUtils.FillText(self.TextContent, vo.content)

    local url = self._data.driftBottle.url --..vo.url
    local strs = CfUtils.Split(url, "/")
    local md5 = ""
    if strs then
        local md5Strs = CfUtils.Split(strs[#strs], ".")
        if md5Strs then
            md5 = checkString(md5Strs[1])
        end
    end
    self.ImgPhoto.Url = url
    self.ImgPhoto.Md5 = md5
    self.ImgPhoto.SavePath = ""
    self.ImgPhoto:LoadSprite()
end

function UIFishPoolDriftingBottleDialog:OnBtnOpen()
    if self._isOpen then
        return
    end
    self._isOpen = true
    CfUtils.PlayAnimator(self.AimRoot, "Go")
end

function UIFishPoolDriftingBottleDialog:OnBtnClose()
    if self._isClose then
        return
    end
    if not self._isOpen then
        return
    end
    self._isClose = true
    cs_coroutine.start(function()
        CfUtils.PlayAnimator(self.AimRoot, "Back")
        coroutine.yield(WaitForSeconds(1.25 + 0.35))
        FishingMgr:GetInstance():SetShuiHuaEffectActive(true, 1)
        CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_bait)
        coroutine.yield(WaitForSeconds(1))
        FishingMgr:GetInstance():SetShuiHuaEffectActive(false)

        if self._cb then
            self._cb()
        end
        UIModule.BackDialog()
    end)
end

function UIFishPoolDriftingBottleDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local id = checkNumber(self._data.driftBottle.id)
        if id <= 0 then
            return
        end

        local vo = FishingUtils.GetFishingDriftBottleVo(id)
        if not vo then
            return
        end
        self:FillSelf(vo)
    end))
    return coWait
end

function UIFishPoolDriftingBottleDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

